-- The pages of the in-game RTX Remix guide (nativeloader_guide.lua draws them). Every text a player
-- reads is marked with N("...") for tools/companion_i18n.py and translated where it is drawn. Items:
--   { "h", text, id = section }        a section heading; it is listed under its page on the left
--   { "p", text }                      a paragraph
--   { "steps", text, text, ... }       numbered steps (an entry may be { text, when = ... })
--   { "list", text, text, ... }        a list (entries as in steps)
--   { "image", path, legend, ... }     a picture; legend entry n explains the badge numbered n
--   { "term", word, meaning }          a word explained
--   { "q", text }                      a symptom, followed by what to do
--   { "tip", text } / { "warn", text } a note / a caution
--   { "code", literal }                text shown as it is (never translated)
--   { "button", label, command, ... }  a button that runs console commands
--   { "link", label, page, section }   a link to another part of the guide
-- Any item may carry when = "r6" (loader 0.11.0 or later), "legacy" (older), "r13" (0.13.0 or
-- later) or "pre13" (older than 0.13.0); the guide reads that from native-loader/status.json.
-- Documented in guide_pages.lua.md beside this file.
local function N(text) return text end

-- A complete config.json: the shipped allowlist, the low tier and GPU dumps off (JSON is not translated).
